const input = $input.first().json || {};

let enrichment = input.enrichment || {};
let leadScore = input.lead_score || {};
let crm = input.crm || {};
let crmSync = input.crm_sync || {};

if (typeof enrichment === "string") enrichment = JSON.parse(enrichment);
if (typeof leadScore === "string") leadScore = JSON.parse(leadScore);
if (typeof crm === "string") crm = JSON.parse(crm);
if (typeof crmSync === "string") crmSync = JSON.parse(crmSync);

function clean(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function normalizePriority(value) {
  const text = clean(value);
  const allowed = ["Low", "Medium", "High", "Urgent"];
  return allowed.includes(text) ? text : "Medium";
}

function normalizeLeadStatus(value) {
  const text = clean(value);
  const allowed = ["qualified", "nurture", "disqualified"];
  return allowed.includes(text) ? text : "nurture";
}

const eventId = Number(input.event_id || input.run_id);
const leadId = Number(input.lead_id);

if (!eventId || Number.isNaN(eventId)) {
  throw new Error("Missing valid event_id/run_id");
}

if (!leadId || Number.isNaN(leadId)) {
  throw new Error("Missing valid lead_id");
}

if (!leadScore || typeof leadScore !== "object") {
  throw new Error("Missing lead_score object from Workflow 04");
}

const normalizedLeadScore = {
  ...leadScore,
  lead_score: Number(leadScore.lead_score || 0),
  priority: normalizePriority(leadScore.priority),
  lead_status: normalizeLeadStatus(leadScore.lead_status)
};

return [
  {
    json: {
      run_id: eventId,
      event_id: eventId,
      external_id: clean(input.external_id),
      event_source: clean(input.event_source) || "website_form",

      lead_id: leadId,
      lead_name: clean(input.lead_name),
      lead_email: clean(input.lead_email),
      lead_phone: clean(input.lead_phone),
      lead_source: clean(input.lead_source || input.event_source),

      company_name: clean(input.company_name),
      company_domain: clean(input.company_domain),
      website_url: clean(input.website_url),

      job_title: clean(input.job_title),
      message: clean(input.message),
      budget: clean(input.budget),
      timeline: clean(input.timeline),
      country: clean(input.country),

      enrichment,
      lead_score: normalizedLeadScore,
      crm,
      crm_sync: crmSync,
      crm_lead_page_id: clean(input.crm_lead_page_id || crmSync.crm_lead_page_id)
    }
  }
];

const data = $input.first().json;

const context = {
  lead: {
    lead_name: data.lead_name,
    lead_email: data.lead_email,
    lead_phone: data.lead_phone,
    job_title: data.job_title,
    source: data.lead_source
  },
  company: {
    company_name: data.company_name,
    company_domain: data.company_domain,
    website_url: data.website_url,
    country: data.country
  },
  request: {
    message: data.message,
    budget: data.budget,
    timeline: data.timeline
  },
  enrichment: data.enrichment,
  score: data.lead_score,
  crm: {
    crm_lead_page_id: data.crm_lead_page_id,
    crm_status: data.crm_sync?.crm_status,
    crm_priority: data.crm_sync?.crm_priority
  }
};

const prompt = `
Create a sales follow-up plan for this scored inbound B2B automation lead.

Return ONLY valid raw JSON.
Do not use markdown.
Do not use code fences.
Do not explain outside JSON.

Rules:
- If lead_status is qualified, create a sales follow-up task.
- If lead_status is nurture, create a softer follow-up task.
- If lead_status is disqualified, do not create a sales task unless there is a clear reason.
- The follow-up must be specific to the lead's stated problem.
- Include a concise email/message draft.
- Include task title, task description, priority, due date offset, and notification text.
- Do not invent facts.

INPUT_JSON:
${JSON.stringify(context)}

Return exactly this JSON schema:

{
  "should_create_follow_up": true,
  "follow_up_type": "sales_discovery",
  "task_title": "",
  "task_description": "",
  "task_priority": "Medium",
  "due_in_days": 1,
  "owner_role": "",
  "draft_message": "",
  "telegram_summary": "",
  "reason": ""
}
`;

return [
  {
    json: {
      ...data,
      follow_up_context: context,
      follow_up_prompt: prompt
    }
  }
];

const raw =
  $json.output ||
  $json.text ||
  $json.content ||
  $json.message ||
  JSON.stringify($json);

const input = $('Build Follow-up Prompt').first().json;

function cleanText(value) {
  if (!value) return "";
  return String(value).trim();
}

function normalizeValue(value, allowed, fallback) {
  const text = cleanText(value);
  return allowed.includes(text) ? text : fallback;
}

function parseBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;
  const text = cleanText(value).toLowerCase();
  return ["true", "yes", "1"].includes(text);
}

function parseJsonFromText(value) {
  let text = String(value || "").trim();

  text = text
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();

  const first = text.indexOf("{");
  const last = text.lastIndexOf("}");

  if (first !== -1 && last !== -1) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

const parsed = parseJsonFromText(raw);

const allowedTypes = [
  "sales_discovery",
  "nurture",
  "disqualified_no_action"
];

const allowedPriorities = [
  "Low",
  "Medium",
  "High",
  "Urgent"
];

let shouldCreate = parseBoolean(parsed.should_create_follow_up);

if (input.lead_score.lead_status === "qualified") {
  shouldCreate = true;
}

if (input.lead_score.lead_status === "disqualified") {
  shouldCreate = false;
}

let dueInDays = Number(parsed.due_in_days);
if (Number.isNaN(dueInDays)) dueInDays = 1;
dueInDays = Math.max(0, Math.min(14, Math.round(dueInDays)));

const dueDate = new Date();
dueDate.setDate(dueDate.getDate() + dueInDays);

const followUp = {
  should_create_follow_up: shouldCreate,
  follow_up_type: normalizeValue(
    parsed.follow_up_type,
    allowedTypes,
    input.lead_score.lead_status === "qualified" ? "sales_discovery" : "nurture"
  ),
  task_title: cleanText(parsed.task_title) || `Follow up with ${input.lead_name || input.company_name || "lead"}`,
  task_description: cleanText(parsed.task_description),
  task_priority: normalizeValue(
    parsed.task_priority,
    allowedPriorities,
    input.lead_score.priority || "Medium"
  ),
  due_in_days: dueInDays,
  due_date: dueDate.toISOString().slice(0, 10),
  owner_role: cleanText(parsed.owner_role || input.lead_score.suggested_owner_role),
  draft_message: cleanText(parsed.draft_message),
  telegram_summary: cleanText(parsed.telegram_summary),
  reason: cleanText(parsed.reason),
  created_at: new Date().toISOString()
};

if (!followUp.task_description) {
  followUp.task_description = [
    `Lead: ${input.lead_name || "Unknown"}`,
    `Company: ${input.company_name || "Unknown"}`,
    `Score: ${input.lead_score.lead_score}/100`,
    `Status: ${input.lead_score.lead_status}`,
    input.lead_score.recommended_next_action
      ? `Recommended next action: ${input.lead_score.recommended_next_action}`
      : ""
  ].filter(Boolean).join("\n");
}

if (!followUp.telegram_summary) {
  followUp.telegram_summary = [
    `New ${input.lead_score.fit_level} fit lead`,
    `${input.lead_name || "Unknown lead"} at ${input.company_name || "Unknown company"}`,
    `Score: ${input.lead_score.lead_score}/100`,
    `Priority: ${input.lead_score.priority}`,
    `Next: ${input.lead_score.recommended_next_action || followUp.task_title}`
  ].join("\n");
}

return [
  {
    json: {
      ...input,
      follow_up: followUp
    }
  }
];

const data = $('Parse Follow-up Plan').first().json;

return [
  {
    json: {
      ...data,
      notion_follow_up_task_id: null,
      follow_up_skipped: true
    }
  }
];

const current = $input.first().json || {};
const data = $('Parse Follow-up Plan').first().json;

const notionTaskId =
  current.id ||
  current.notion_follow_up_task_id ||
  null;

const followUpResult = {
  ...data.follow_up,
  notion_follow_up_task_id: notionTaskId,
  follow_up_created: Boolean(notionTaskId),
  follow_up_skipped: !notionTaskId,
  completed_at: new Date().toISOString()
};

return [
  {
    json: {
      ...data,
      follow_up_result: followUpResult,
      notion_follow_up_task_id: notionTaskId
    }
  }
];

const data = $('Build Follow-up Result').first().json;

return [
  {
    json: {
      success: true,
      event_id: data.event_id,
      lead_id: data.lead_id,
      lead_status: data.lead_score.lead_status,
      lead_score: data.lead_score.lead_score,
      processing_status: "completed",
      notified_sales: false
    }
  }
];
